INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das BIOS ein wichtiger Bestandteil bei der Installation eines Systems?', 2, '[{"text": "Ja", "correct": true, "because": "Startet den Computer"}, {"text": "Nein", "correct": false, "because": "Es ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt das BIOS bei der Installation?', 3, '[{"text": "Hardwareinitialisierung und Systemstart", "correct": true, "because": "Grundfunktion"}, {"text": "Betriebssystem installieren", "correct": false, "because": "Folgeschritt"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Software"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das BIOS ist auf dem Motherboard gespeichert. b) Es ist ein Betriebssystem.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Firmware"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt das BIOS bei der Installation?', 4, '[{"text": "POST (Power-On Self-Test)", "correct": true, "because": "Prüft Hardware"}, {"text": "Unklare Funktionen", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Bootreihenfolge festlegen", "correct": true, "because": "Startmedium"}, {"text": "Hardwareerkennung", "correct": true, "because": "Initialisiert Geräte"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Computer ohne BIOS starten?', 2, '[{"text": "Nein", "correct": true, "because": "Initialisierung fehlt"}, {"text": "Ja", "correct": false, "because": "Unmöglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das BIOS bei der Installation?', 3, '[{"text": "Startet den Bootprozess", "correct": true, "because": "Lädt Betriebssystem"}, {"text": "Daten formatieren", "correct": false, "because": "Betriebssystemaufgabe"}, {"text": "Netzwerkverbindung herstellen", "correct": false, "because": "Andere Schichten"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das BIOS nur bei der Erstinstallation relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Jeder Start benötigt es"}, {"text": "Ja", "correct": false, "because": "Dauerhafte Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat der POST im BIOS?', 3, '[{"text": "Hardware auf Fehler prüfen", "correct": true, "because": "Selbsttest"}, {"text": "Betriebssystem laden", "correct": false, "because": "Bootloader-Aufgabe"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Software"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das BIOS kann aktualisiert werden. b) Es ist nicht auf dem Motherboard.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, fest integriert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne funktionierendes BIOS?', 3, '[{"text": "System startet nicht", "correct": true, "because": "Grundfunktion fehlt"}, {"text": "Betriebssystem lädt schneller", "correct": false, "because": "Unsinn"}, {"text": "Hardware bleibt aktiv", "correct": false, "because": "Kein Start möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das BIOS ohne Betriebssystem arbeiten?', 2, '[{"text": "Ja", "correct": true, "because": "Unabhängige Firmware"}, {"text": "Nein", "correct": false, "because": "Eigenständig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt eine BIOS-Einstellung?', 3, '[{"text": "Bootreihenfolge auf USB setzen", "correct": true, "because": "Konkret und real"}, {"text": "Irgendwas einstellen", "correct": false, "because": "Zu vage"}, {"text": "Netzwerkverbindung konfigurieren", "correct": false, "because": "Andere Ebene"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist das BIOS nur für Desktops relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Notebooks"}, {"text": "Ja", "correct": false, "because": "Breite Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat das BIOS?', 4, '[{"text": "Firmware", "correct": true, "because": "Fest im System"}, {"text": "Unklare Software", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Hardwaresteuerung", "correct": true, "because": "Initialisiert Geräte"}, {"text": "Bootfähigkeit", "correct": true, "because": "Startet System"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss das BIOS regelmäßig aktualisiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei Bedarf"}, {"text": "Ja", "correct": false, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das BIOS beim Systemstart?', 3, '[{"text": "Lädt den Bootloader", "correct": true, "because": "Startsequenz"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Software"}, {"text": "Netzwerkverbindung herstellen", "correct": false, "because": "Andere Schicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann das BIOS ohne Strom arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Stromversorgung nötig"}, {"text": "Ja", "correct": false, "because": "Unmöglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die BIOS-Installation?', 3, '[{"text": "Motherboard-Kompatibilität", "correct": true, "because": "Hardwareabhängig"}, {"text": "Monitorgröße", "correct": false, "because": "Irrelevant"}, {"text": "Tastaturlayout", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das BIOS wird über ein Update-Tool aktualisiert. b) Es ist nur für Windows relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, OS-unabhängig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen des BIOS bei der Installation?', 3, '[{"text": "Sicheres Hochfahren des Systems", "correct": true, "because": "Fördert Start"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Hardwareerkennung", "correct": false, "because": "Fördert Initialisierung"}]');
